function o(r){if(!r)return"—";const e=new Date(r);if(Number.isNaN(e.getTime()))return r;const t=n=>String(n).padStart(2,"0");return`${e.getFullYear()}-${t(e.getMonth()+1)}-${t(e.getDate())} ${t(e.getHours())}:${t(e.getMinutes())}`}function a(r){if(!r)return"—";const e=new Date(r).getTime();if(Number.isNaN(e))return"—";const t=Math.round((Date.now()-e)/1e3);return t<60?"刚刚":t<3600?`${Math.floor(t/60)} 分钟前`:t<86400?`${Math.floor(t/3600)} 小时前`:`${Math.floor(t/86400)} 天前`}export{o as f,a as r};
